def _norm(value: str) -> str:
    return re.sub(r"[^A-Z0-9]+", "", str(value or "").upper())


def seed_tiom_temp_reference_data(db: Session) -> dict:
    """Idempotent seed used only when TIOM_TEMP_REFERENCE_SEED=true."""
    locations = list(db.scalars(select(Location)))
    by_norm = {_norm(x.location_name): x for x in locations if x.location_name}
    by_id = {x.location_id: x for x in locations}

    resolved: dict[str, str] = {}

    def ensure_location(item: dict) -> str:
        preferred = item["id"]
        obj = by_id.get(preferred) or by_norm.get(_norm(item["name"]))
        if not obj:
            obj = Location(
                location_id=preferred,
                location_name=item["name"],
                location_type=item.get("type"),
                active=True,
            )
            db.add(obj)
            db.flush()
            by_id[obj.location_id] = obj
            by_norm[_norm(obj.location_name)] = obj
        else:
            obj.active = True
            if not obj.location_type:
                obj.location_type = item.get("type")
        resolved[preferred] = obj.location_id
        for alias in item.get("aliases") or []:
            row = db.get(LocationAlias, alias)
            if not row:
                db.add(LocationAlias(alias=alias, location_id=obj.location_id, direction="ANY", active=True))
            else:
                row.location_id = obj.location_id
                row.active = True
        return obj.location_id

    for item in REFERENCE["sources"] + REFERENCE["destinations"]:
        ensure_location(item)

    for item in REFERENCE["equipment"]:
        obj = db.get(Equipment, item["id"])
        if not obj:
            obj = Equipment(
                machine_id=item["id"],
                type=item["type"],
                group=item["group"],
                active=True,
            )
            db.add(obj)
        else:
            obj.active = True
            if not obj.type:
                obj.type = item["type"]
            if not obj.group:
                obj.group = item["group"]

    for activity in REFERENCE["activities"]:
        obj = db.get(ActivityMaster, activity)
        if not obj:
            db.add(ActivityMaster(activity=activity, vehicle_required=False, active=True))
        else:
            obj.active = True

    db.flush()

    lead_created = 0
    lead_updated = 0
    for item in LEADS:
        src = resolved[item["src"]]
        dst = resolved[item["dest"]]
        lead_id = f'{src}|{int(item["rl"])}|{dst}|{item["mode"]}'
        obj = db.get(TiomLeadDistance, lead_id)
        if not obj:
            obj = TiomLeadDistance(
                lead_id=lead_id,
                source_location_id=src,
                bench_rl_m=int(item["rl"]),
                destination_location_id=dst,
                route_mode=item["mode"],
                lead_km=Decimal(str(item["km"])),
                material_scope=item["scope"],
                source_document=item["doc"],
                active=True,
                entered_by="TEMP_SEED",
            )
            db.add(obj)
            lead_created += 1
        else:
            obj.lead_km = Decimal(str(item["km"]))
            obj.material_scope = item["scope"]
            obj.source_document = item["doc"]
            obj.active = True
            lead_updated += 1

    db.flush()
    counts = {
        "sources": len(REFERENCE["sources"]),
        "destinations": len(REFERENCE["destinations"]),
        "equipment": len(REFERENCE["equipment"]),
        "activities": len(REFERENCE["activities"]),
        "leadRules": len(LEADS),
        "leadCreated": lead_created,
        "leadUpdated": lead_updated,
    }
    log.info("TIOM_TEMP_REFERENCE_SEED_OK %s", counts)
    return counts
